"""The enforcement point. The model proposes a statement; this decides whether it runs.

The rule the prompt cannot express: an irreversible statement against a production
target is refused unless a capability for that exact resource was granted out of band.
Refusal is a normal, logged outcome, not an error the agent may retry around.
"""


class Refused(Exception):
    """Raised instead of performing the side effect."""


IRREVERSIBLE_PREFIXES = ("drop ", "delete ", "truncate ", "alter ", "update ")
ALLOWLIST_TABLES = frozenset({"staging_events"})


def decide(statement: str, target_env: str, granted: frozenset[str]) -> None:
    lowered = statement.strip().lower()
    if not any(lowered.startswith(p) for p in IRREVERSIBLE_PREFIXES):
        return
    if target_env != "production":
        return
    touched = {t for t in ALLOWLIST_TABLES if t in lowered}
    if not touched or not touched <= granted:
        raise Refused(
            f"irreversible statement refused: no capability granted for {target_env}"
        )
